/**
 * Digital products sold by SkynetLabs on Etsy (shop 59069182) and Gumroad.
 * The list lives in products.json, generated by scripts/sync-digital-products.py
 * from the live stores (do not edit by hand). Prices are store prices at sync
 * time and may change on the store; the page says so.
 */
import data from "./products.json";

export type DigitalProduct = {
  store: "etsy" | "gumroad";
  id: string; // Etsy listing id or Gumroad product id
  slug: string; // image file name in /public/digital-products
  name: string;
  forWho: string;
  inside: string;
  price: number;
  url: string; // store product URL
  category: string;
  image: string; // /digital-products/<slug>.webp
};

export const CATEGORY_ORDER = [
  "Real Estate Agent Tools",
  "Insurance & Tax",
  "Home Services",
  "Med Spa & Clinics",
  "Lash & Brow Forms",
  "Pro Services",
  "VA & Social Media Kits",
  "Small Business Systems",
  "Online Sellers",
  "Christmas Printables",
] as const;

export const DIGITAL_PRODUCTS = data as DigitalProduct[];

export const STORE_LABEL: Record<DigitalProduct["store"], string> = {
  etsy: "Etsy",
  gumroad: "Gumroad",
};

export const categoryAnchor = (c: string) =>
  c
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");

export type ProductGroup = { category: string; products: DigitalProduct[] };

/** Products grouped by category in CATEGORY_ORDER; unknown categories go last. */
export function groupByCategory(
  products: DigitalProduct[] = DIGITAL_PRODUCTS,
): ProductGroup[] {
  const known: string[] = [...CATEGORY_ORDER];
  const extra = [...new Set(products.map((p) => p.category))].filter(
    (c) => !known.includes(c),
  );
  return [...known, ...extra]
    .map((category) => ({
      category,
      products: products.filter((p) => p.category === category),
    }))
    .filter((g) => g.products.length > 0);
}
